import json

test_input = [
    [0, 0, 6, 0, 0, 0, 0, 0, 6],
    [0, 6, 0, 6, 0, 0, 0, 6, 0],
    [6, 0, 0, 0, 6, 0, 6, 0, 0],
    [0, 0, 0, 0, 0, 6, 0, 0, 0]
]

def solve(grid):
    """Fill enclosed regions with 2"""
    h = len(grid)
    w = len(grid[0])

    # Get marker positions (non-zero cells)
    markers = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                markers.add((r, c))

    result = [row[:] for row in grid]

    # Flood fill from top-left to find reachable cells (not enclosed)
    visited = [[False]*w for _ in range(h)]
    stack = [(0, 0)]
    visited[0][0] = True

    while stack:
        r, c = stack.pop()

        # Check all 4 directions
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not visited[nr][nc] and grid[nr][nc] == 0:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    # Cells NOT visited AND are 0 should be filled
    for r in range(h):
        for c in range(w):
            if not visited[r][c] and grid[r][c] == 0:
                result[r][c] = 2

    return result

result = solve(test_input)
print("Flood fill result:")
for row in result:
